<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Super Admin','IT/System Administrator');check_csrf();
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='database'){
 $dir=dirname(__DIR__).'/storage/backups';if(!is_dir($dir))mkdir($dir,0700,true);$file=$dir.'/college_management_'.date('Ymd_His').'.sql';$bin=getenv('CMS_MYSQLDUMP_BIN')?:((strtoupper(substr(PHP_OS,0,3))==='WIN' && is_file('C:/xampp/mysql/bin/mysqldump.exe'))?'C:/xampp/mysql/bin/mysqldump.exe':'mysqldump');$dbHost=$GLOBALS['app']['db_host']??'127.0.0.1';$dbName=$GLOBALS['app']['db_name']??'college_management';$dbUser=$GLOBALS['app']['db_user']??'root';$dbPass=$GLOBALS['app']['db_pass']??'';$cmd=escapeshellarg($bin).' -h '.escapeshellarg($dbHost).' -u '.escapeshellarg($dbUser).' '.($dbPass!==''?'--password='.escapeshellarg($dbPass).' ':'').escapeshellarg($dbName).' > '.escapeshellarg($file).' 2>&1';exec($cmd,$out,$code);$st=$code===0?'Success':'Failed';db()->prepare('INSERT INTO backup_logs(created_by,backup_type,file_name,status) VALUES(?,?,?,?,?)')->execute([actor_id(),'database',basename($file),$st]);AuditService::log('BACKUP','system',null,$st.' database backup');$_SESSION['flash']=[$code===0?'success':'danger',$code===0?'Backup created: '.basename($file):'Backup failed. Configure mysqldump path/credentials.'];redirect('backup.php');}
